      'myAnbari \u0627\u0634\u062a\u0631\u0627\u06a9\u06cc \u0627\u0633\u062a \u0648 \u0646\u0633\u062e\u0647\u0654 \u0631\u0627\u06cc\u06af\u0627\u0646 \u0646\u062f\u0627\u0631\u062f\u061b \u0627\u06af\u0631 \u0631\u0627\u0636\u06cc \u0646\u0628\u0648\u062f\u06cc\u062f\u060c \u062a\u0627 \u0686\u0646\u062f \u0631\u0648\u0632 \u0628\u0639\u062f \u0627\u0632 \u062e\u0631\u06cc\u062f \u067e\u0648\u0644\u062a\u0627\u0646 \u0628\u0631\u0645\u06cc\u200c\u06af\u0631\u062f\u062f. \u062f\u0641\u062a\u0631 \u062d\u0633\u0627\u0628\u060c \u0686\u06a9\u200c\u0647\u0627\u060c \u0641\u0631\u0648\u0634 \u0646\u0633\u06cc\u0647 \u0648 \u0647\u0645\u06a9\u0627\u0631\u0627\u0646 \u062f\u0631 \u0627\u0634\u062a\u0631\u0627\u06a9 \xab\u067e\u0644\u0627\u0633\xbb \u0647\u0633\u062a\u0646\u062f.':
        'myAnbari \u0627\u0634\u062a\u0631\u0627\u0643 \u0628\u0644\u0627 \u0646\u0633\u062e\u0629 \u0645\u062c\u0627\u0646\u064a\u0629\u061b \u0625\u0646 \u0644\u0645 \u062a\u0643\u0646 \u0631\u0627\u0636\u064a\u064b\u0627 \u064a\u0639\u0648\u062f \u0645\u0627\u0644\u0643 \u062e\u0644\u0627\u0644 \u0623\u064a\u0627\u0645 \u0645\u0646 \u0627\u0644\u0634\u0631\u0627\u0621. \u062f\u0641\u062a\u0631 \u0627\u0644\u062d\u0633\u0627\u0628\u0627\u062a \u0648\u0627\u0644\u0634\u064a\u0643\u0627\u062a \u0648\u0627\u0644\u0628\u064a\u0639 \u0627\u0644\u0622\u062c\u0644 \u0648\u0627\u0644\u0645\u0648\u0638\u0641\u0648\u0646 \u0641\u064a \u062e\u0637\u0629 \xab\u0628\u0644\u0633\xbb.',
