        '\u0623\u0631\u062f\u064a\u0628\u0647\u0634\u062a',
      '\u0627\u0631\u0633\u0627\u0644': '\u0625\u0631\u0633\u0627\u0644',
      '\u0627\u0631\u0633\u0627\u0644 \u0627\u0639\u0644\u0627\u0646 \u0622\u0632\u0645\u0627\u06cc\u0634\u06cc':
        '\u0625\u0631\u0633\u0627\u0644 \u0625\u0634\u0639\u0627\u0631 \u062a\u062c\u0631\u064a\u0628\u064a',
      '\u0627\u0631\u0633\u0627\u0644 \u0627\u0639\u0644\u0627\u0646 \u06af\u0648\u0634\u06cc \u0627\u0646\u062c\u0627\u0645 \u0646\u0634\u062f\u061b \u062f\u0648\u0628\u0627\u0631\u0647 \u062a\u0644\u0627\u0634 \u06a9\u0646.':
        '\u062a\u0639\u0630\u0651\u0631 \u0625\u0631\u0633\u0627\u0644 \u0625\u0634\u0639\u0627\u0631 \u0627\u0644\u0647\u0627\u062a\u0641\u061b \u062d\u0627\u0648\u0644 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649.',
      '\u0627\u0631\u0633\u0627\u0644 \u0627\u06cc\u0646 \u062a\u063a\u06cc\u06cc\u0631 \u067e\u0633 \u0627\u0632 \u06f6 \u062a\u0644\u0627\u0634 \u0645\u062a\u0648\u0642\u0641 \u0634\u062f. \u0628\u0631\u0627\u06cc \u0627\u0631\u0633\u0627\u0644 \u062f\u0648\u0628\u0627\u0631\u0647 \u0627\u0646\u062a\u062e\u0627\u0628 \u06a9\u0646\u06cc\u062f.':
        '\u062a\u0648\u0642\u0641 \u0625\u0631\u0633\u0627\u0644 \u0647\u0630\u0627 \u0627\u0644\u062a\u0639\u062f\u064a\u0644 \u0628\u0639\u062f \u0666 \u0645\u062d\u0627\u0648\u0644\u0627\u062a. \u0627\u0636\u063a\u0637 \u0644\u0625\u0639\u0627\u062f\u0629 \u0627\u0644\u0625\u0631\u0633\u0627\u0644.',
