        '\u0627\u0644\u0625\u0631\u0633\u0627\u0644 \u0625\u0644\u0649 \u0627\u0644\u0628\u0631\u064a\u062f \u0628\u062f\u0644\u0627\u064b \u0645\u0646 \u0627\u0644\u0631\u0642\u0645',
