        '\u0645\u0644\u062e\u0635 \u0634\u0647\u0631\u0643 \u0627\u0644\u0623\u0648\u0644',
      '\u062e\u0648\u0627\u0646\u062f\u0646 PDF':
        '\u0642\u0631\u0627\u0621\u0629 PDF',
      '\u062e\u0648\u0627\u0646\u062f\u0646 PDF \u0628\u0627 \u0647\u0648\u0634 \u0645\u0635\u0646\u0648\u0639\u06cc':
        '\u0642\u0631\u0627\u0621\u0629 PDF \u0628\u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064a',
