      '\u062e\u0648\u0627\u0646\u062f\u0646 \u0633\u0646\u062f \u0628\u0627 \u0647\u0648\u0634 \u0645\u0635\u0646\u0648\u0639\u06cc':
        '\u0642\u0631\u0627\u0621\u0629 \u0627\u0644\u0645\u0633\u062a\u0646\u062f \u0628\u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064a',
      '\u062e\u0648\u0627\u0646\u062f\u0646 \u0639\u06a9\u0633 \u0645\u0645\u06a9\u0646 \u0646\u0634\u062f ({reason})\u061b \u062e\u0627\u0646\u0647\u200c\u0647\u0627 \u0631\u0627 \u062e\u0648\u062f\u062a \u067e\u0631 \u06a9\u0646. \u0639\u06a9\u0633 \u06a9\u0646\u0627\u0631 \u0686\u06a9 \u0645\u06cc\u200c\u0645\u0627\u0646\u062f.':
        '\u062a\u0639\u0630\u0651\u0631\u062a \u0642\u0631\u0627\u0621\u0629 \u0627\u0644\u0635\u0648\u0631\u0629 ({reason}). \u0627\u0645\u0644\u0623 \u0627\u0644\u062d\u0642\u0648\u0644 \u0628\u0646\u0641\u0633\u0643\u061b \u062a\u0628\u0642\u0649 \u0627\u0644\u0635\u0648\u0631\u0629 \u0645\u0639 \u0627\u0644\u0634\u064a\u0643.',
      '\u062e\u0648\u0627\u0646\u062f\u0646 \u0645\u0648\u062c\u0648\u062f\u06cc (curl)':
        '\u0642\u0631\u0627\u0621\u0629 \u0627\u0644\u0645\u062e\u0632\u0648\u0646 (curl)',
      '\u062e\u0648\u0627\u0646\u062f\u0646 \u0647\u0645\u0647':
        '\u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0643\u0644 \u0643\u0645\u0642\u0631\u0648\u0621',
      '\u062e\u0648\u0627\u0646\u062f\u0647\u200c\u0634\u062f\u0647':
        '\u0645\u0642\u0631\u0648\u0621\u0629',
      '\u062e\u0648\u0627\u0646\u062f\u0647\u200c\u0646\u0634\u062f\u0647':
        '\u063a\u064a\u0631 \u0645\u0642\u0631\u0648\u0621',
      '\u062e\u0648\u0627\u0647': '\u062e\u0648\u0627\u0647',
      '\u062e\u0648\u0628': '\u062c\u064a\u062f',
      '\u062e\u0648\u062f\u062a + {n} \u06a9\u0627\u0631\u0645\u0646\u062f':
        '\u0623\u0646\u062a + {n} \u0645\u0648\u0638\u0641\u064a\u0646',
      '\u062e\u0648\u062f\u0645 \u062f\u0631\u0633\u062a \u0645\u06cc\u200c\u06a9\u0646\u0645 \u0648 \u0645\u06cc\u200c\u0641\u0631\u0648\u0634\u0645':
        '\u0623\u0635\u0646\u0639 \u0628\u0646\u0641\u0633\u064a \u0648\u0623\u0628\u064a\u0639',
