      '\u062f\u0633\u062a\u0648\u0631 \u0633\u0627\u062e\u062a \u0630\u062e\u06cc\u0631\u0647 \u0634\u062f.':
        '\u062a\u0645 \u062d\u0641\u0638 \u0648\u0635\u0641\u0629 \u0627\u0644\u062a\u0635\u0646\u064a\u0639.',
      '\u062f\u0633\u062a\u0648\u0631 \u0633\u0627\u062e\u062a \u0648 \u0645\u0646\u0648':
        '\u0627\u0644\u0648\u0635\u0641\u0627\u062a \u0648\u0627\u0644\u0642\u0627\u0626\u0645\u0629',
