        '\u0627\u0644\u0623\u062c\u0647\u0632\u0629 \u0627\u0644\u0646\u0634\u0637\u0629',
      '\u062f\u0633\u062a\u06af\u0627\u0647\u200c\u0647\u0627\u06cc \u0647\u0645\u06a9\u0627\u0631\u0627\u0646':
        '\u0623\u062c\u0647\u0632\u0629 \u0641\u0631\u064a\u0642 \u0627\u0644\u0639\u0645\u0644',
