      '\u062f\u0639\u0648\u062a \u0648 \u0647\u0645\u06a9\u0627\u0631\u06cc \u06a9\u0627\u0631\u06a9\u0646\u0627\u0646':
        '\u062f\u0639\u0648\u0629 \u0627\u0644\u0645\u0648\u0638\u0641\u064a\u0646 \u0648\u0627\u0644\u062a\u0639\u0627\u0648\u0646',
      '\u062f\u0639\u0648\u062a \u067e\u0630\u06cc\u0631\u0641\u062a\u0647 \u0634\u062f.':
        '\u062a\u0645 \u0642\u0628\u0648\u0644 \u0627\u0644\u062f\u0639\u0648\u0629.',
      '\u062f\u0639\u0648\u062a \u06a9\u0646':
        '\u0627\u062f\u0639\u064f \u0627\u0644\u0622\u0646',
      '\u062f\u0639\u0648\u062a\u200c\u0647\u0627\u06cc \u062f\u0631 \u0627\u0646\u062a\u0638\u0627\u0631':
        '\u0627\u0644\u062f\u0639\u0648\u0627\u062a \u0627\u0644\u0645\u0639\u0644\u0642\u0629',
      '\u062f\u0641\u062a\u0631': '\u062f\u0641\u062a\u0631',
