      '\u062f\u0641\u062a\u0631 \u0646\u0633\u06cc\u0647\u200c\u0645 \u062f\u06cc\u06af\u0647 \u06af\u0645 \u0646\u0645\u06cc\u200c\u0634\u0647':
        '\u062f\u0641\u062a\u0631 \u0627\u0644\u062f\u064e\u0651\u064a\u0646 \u0644\u0645 \u064a\u0639\u062f \u064a\u0636\u064a\u0639',
      '\u062f\u0641\u062a\u0631 \u0648 \u06a9\u0627\u063a\u0630':
        '\u0627\u0644\u062f\u0641\u062a\u0631 \u0648\u0627\u0644\u0648\u0631\u0642',
      '\u062f\u0641\u062a\u0631 \u06a9\u0627\u063a\u0630\u06cc \u0628\u0627\u0628\u0627\u060c \u062d\u0627\u0644\u0627 \u062a\u0648\u06cc \u06af\u0648\u0634\u06cc':
        '\u062f\u0641\u062a\u0631 \u0628\u0627\u0628\u0627 \u0627\u0644\u0648\u0631\u0642\u064a\u060c \u0627\u0644\u0622\u0646 \u0641\u064a \u0647\u0627\u062a\u0641\u0643',
      '\u062f\u0641\u062a\u0631 \u06a9\u0627\u0645\u0644 {name}':
        '\u0627\u0644\u062f\u0641\u062a\u0631 \u0627\u0644\u0643\u0627\u0645\u0644 \u0644\u0640{name}',
      '\u062f\u0641\u062a\u0631 \u06af\u0645 \u0628\u0634\u0647\u060c \u0647\u0645\u0647\u200c\u0686\u06cc\u0632 \u0631\u0641\u062a\u0647':
        '\u0625\u0646 \u0636\u0627\u0639 \u0627\u0644\u062f\u0641\u062a\u0631 \u0636\u0627\u0639 \u0643\u0644 \u0634\u064a\u0621',
