        '\u0647\u0630\u0627 \u0627\u0644\u0631\u0642\u0645 \u0628\u0627\u0644\u0636\u0628\u0637',
      '\u062f\u0642\u06cc\u0642\u0647': '\u062f\u0642\u064a\u0642\u0629',
      '\u062f\u0644\u0627\u0631': '\u062f\u0648\u0644\u0627\u0631',
      '\u062f\u0644\u0627\u0631 \u0627\u0645\u0631\u0648\u0632: {amount}':
        '\u0627\u0644\u062f\u0648\u0644\u0627\u0631 \u0627\u0644\u064a\u0648\u0645: {amount}',
