      '\u062f\u0644\u06cc\u0644\u0634 \u0631\u0648\u0634\u0646 \u0646\u06cc\u0633\u062a.':
        '\u0627\u0644\u0633\u0628\u0628 \u063a\u064a\u0631 \u0648\u0627\u0636\u062d.',
      '\u062f\u0645\u067e\u0627\u06cc\u06cc': '\u0634\u0628\u0634\u0628',
      '\u062f\u0647': '\u0639\u0634\u0631\u0629',
      '\u062f\u0648': '\u0627\u062b\u0646\u0627\u0646',
      '\u062f\u0648 \u0627\u06cc\u06a9\u0633 \u0644\u0627\u0631\u062c': 'XXL',
