        '\u0627\u0644\u0623\u0633\u0626\u0644\u0629 \u0627\u0644\u0634\u0627\u0626\u0639\u0629',
      '\u0633\u0627\u0628\u0642\u0647': '\u0627\u0644\u0633\u062c\u0644',
