        '\u0635\u0648\u0631\u0629 \u0627\u0644\u062a\u064f\u0642\u0637\u062a \u0645\u0633\u0628\u0642\u0627\u064b',
      '\u0639\u06cc\u062f\u06cc': '\u0639\u064a\u062f\u064a\u0629',
      '\u0641': '\u0641',
      '\u0641\u0627\u0631\u0633\u06cc':
        '\u0627\u0644\u0641\u0627\u0631\u0633\u064a\u0629',
