        '\u0628\u0633\u064a\u0637 \u0648\u0628\u0644\u063a\u062a\u0643',
      '\u0641\u0627\u0633\u062f': '\u0641\u0627\u0633\u062f',
      '\u0641\u0627\u06a9\u062a\u0648\u0631':
        '\u0641\u0627\u062a\u0648\u0631\u0629',
      '\u0641\u0627\u06a9\u062a\u0648\u0631 \u0627\u062e\u062a\u0635\u0627\u0635\u06cc \u0641\u0631\u0648\u0634\u06af\u0627\u0647':
        '\u0641\u0627\u062a\u0648\u0631\u0629 \u0627\u0644\u0645\u062a\u062c\u0631 \u0627\u0644\u0645\u062e\u0635\u0635\u0629',
