      '\u0641\u0627\u06a9\u062a\u0648\u0631 \u062e\u0631\u06cc\u062f {no}':
        '\u0641\u0627\u062a\u0648\u0631\u0629 \u0634\u0631\u0627\u0621 {no}',
      '\u0641\u0627\u06a9\u062a\u0648\u0631 \u062f\u0631 \u06af\u0627\u0644\u0631\u06cc \u0630\u062e\u06cc\u0631\u0647 \u0634\u062f.':
        '\u062a\u0645 \u062d\u0641\u0638 \u0627\u0644\u0641\u0627\u062a\u0648\u0631\u0629 \u0641\u064a \u0627\u0644\u0645\u0639\u0631\u0636.',
