      '\u0641\u0631\u0633\u062a\u0627\u062f\u0646 \u0639\u06a9\u0633 \u06cc\u0627 \u0641\u0627\u06cc\u0644':
        '\u0625\u0631\u0633\u0627\u0644 \u0635\u0648\u0631\u0629 \u0623\u0648 \u0645\u0644\u0641',
