      '\u0646\u0635\u0641': '\u0646\u0635\u0641',
      '\u0646\u0638\u0631\u062a \u062f\u0631\u0628\u0627\u0631\u0647\u0654 myAnbari \u0686\u06cc\u0647\u061f':
        '\u0645\u0627 \u0631\u0623\u064a\u0643 \u0641\u064a myAnbari\u061f',
      '\u0646\u0641\u0631\u0647': '\u0623\u0634\u062e\u0627\u0635',
      '\u0646\u0642\u0627\u0634\u06cc': '\u062f\u0647\u0627\u0646',
      '\u0646\u0642\u062f \u0648 \u06a9\u0627\u0631\u062a':
        '\u0646\u0642\u062f\u064b\u0627 \u0648\u0628\u0627\u0644\u0628\u0637\u0627\u0642\u0629',
