      '\u0646\u0642\u0631\u0647\u200c\u0627\u06cc': '\u0641\u0636\u064a',
      '\u0646\u0642\u0634 \u0634\u0645\u0627: {role}':
        '\u062f\u0648\u0631\u0643: {role}',
      '\u0646\u0645\u0627\u062f \u0627\u0639\u062a\u0645\u0627\u062f \u0627\u0644\u06a9\u062a\u0631\u0648\u0646\u06cc\u06a9\u06cc':
        '\u0634\u0639\u0627\u0631 \u0627\u0644\u062b\u0642\u0629 \u0627\u0644\u0625\u0644\u0643\u062a\u0631\u0648\u0646\u064a\u0629',
      '\u0646\u0645\u0627\u062f \u0627\u0639\u062a\u0645\u0627\u062f \u062f\u0631\u06af\u0627\u0647 \u067e\u0631\u062f\u0627\u062e\u062a \u0628\u06cc\u062a\u200c\u067e\u06cc':
        '\u0634\u0639\u0627\u0631 \u0627\u0644\u062b\u0642\u0629 \u0644\u0628\u0648\u0627\u0628\u0629 \u0627\u0644\u062f\u0641\u0639 \u0628\u064a\u062a \u0628\u064a',
