      '\u0647\u0632\u06cc\u0646\u0647 \u062b\u0628\u062a \u0634\u062f':
        '\u062a\u0645 \u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u0645\u0635\u0631\u0648\u0641',
      '\u062d\u0630\u0641 \u0647\u0632\u06cc\u0646\u0647':
        '\u062d\u0630\u0641 \u0627\u0644\u0645\u0635\u0631\u0648\u0641',
      '\xab{name}\xbb\u060c {amount} \u062d\u0630\u0641 \u0634\u0648\u062f\u061f':
        '\u0647\u0644 \u062a\u0631\u064a\u062f \u062d\u0630\u0641 \xab{name}\xbb\u060c {amount}\u061f',
