        '\u0631\u0635\u064a\u062f \u0627\u0644\u0645\u0634\u062a\u0631\u064a \u062d\u062a\u0649 \u0627\u0644\u064a\u0648\u0645',
      '\u0637\u0644\u0628 \u062e\u0631\u06cc\u062f\u0627\u0631 \u062a\u0627 \u0627\u0645\u0631\u0648\u0632':
        '\u0631\u0635\u064a\u062f \u062f\u0627\u0626\u0646 \u0644\u0644\u0645\u0634\u062a\u0631\u064a \u062d\u062a\u0649 \u0627\u0644\u064a\u0648\u0645',
      '\u0634\u0645\u0627\u0631\u0647\u0654': '\u0631\u0642\u0645',
      '\u0645\u0645\u0646\u0648\u0646 \u06a9\u0647 \u062e\u0631\u06cc\u062f \u06a9\u0631\u062f\u06cc':
        '\u0634\u0643\u0631\u064b\u0627 \u0644\u062a\u0633\u0648\u0651\u0642\u0643 \u0645\u0639\u0646\u0627',
      '{shop}: \u0641\u0627\u06a9\u062a\u0648\u0631 {no} \u0628\u0647 \u0645\u0628\u0644\u063a {total} \u062a\u0648\u0645\u0627\u0646 (\u062a\u062e\u0641\u06cc\u0641 {discount}). \u0645\u0634\u0627\u0647\u062f\u0647: {link}':
        '{shop}: \u0627\u0644\u0641\u0627\u062a\u0648\u0631\u0629 {no} \u0628\u0645\u0628\u0644\u063a {total} \u062a\u0648\u0645\u0627\u0646 (\u062e\u0635\u0645 {discount}). \u0639\u0631\u0636: {link}',
      '{shop}: \u0641\u0627\u06a9\u062a\u0648\u0631 {no} \u0628\u0647 \u0645\u0628\u0644\u063a {total} \u062a\u0648\u0645\u0627\u0646 (\u062a\u062e\u0641\u06cc\u0641 {discount}).':
        '{shop}: \u0627\u0644\u0641\u0627\u062a\u0648\u0631\u0629 {no} \u0628\u0645\u0628\u0644\u063a {total} \u062a\u0648\u0645\u0627\u0646 (\u062e\u0635\u0645 {discount}).',
      '\xab\u0686\u0627\u067e\xbb \u0645\u0633\u062a\u0642\u06cc\u0645 \u0635\u0641\u062d\u0647\u0654 \u067e\u0631\u06cc\u0646\u062a\u0631 \u0631\u0627 \u0628\u0627\u0632 \u0645\u06cc\u200c\u06a9\u0646\u062f. \u0631\u0646\u06af \u0648 \u0644\u0648\u06af\u0648 \u0645\u062b\u0644 \u0642\u0628\u0644 \u0627\u0632 \xab\u0637\u0631\u062d\u200c\u0647\u0627\xbb.':
        '\xab\u0637\u0628\u0627\u0639\u0629\xbb \u062a\u0641\u062a\u062d \u0646\u0627\u0641\u0630\u0629 \u0627\u0644\u0637\u0627\u0628\u0639\u0629 \u0645\u0628\u0627\u0634\u0631\u0629. \u0627\u0644\u0623\u0644\u0648\u0627\u0646 \u0648\u0627\u0644\u0634\u0639\u0627\u0631 \u0645\u0646 \xab\u0627\u0644\u062a\u0635\u0627\u0645\u064a\u0645\xbb \u0643\u0645\u0627 \u0643\u0627\u0646.',
