        '\u0627\u0644\u0641\u0648\u0627\u062a\u064a\u0631 ({n})',
      '\u0647\u0646\u0648\u0632 \u0641\u0627\u06a9\u062a\u0648\u0631\u06cc \u0628\u0627 \u0627\u06cc\u0646 \u0634\u062e\u0635 \u062b\u0628\u062a \u0646\u0634\u062f\u0647.':
        '\u0644\u0627 \u062a\u0648\u062c\u062f \u0641\u0648\u0627\u062a\u064a\u0631 \u0645\u0639 \u0647\u0630\u0627 \u0627\u0644\u0634\u062e\u0635 \u0628\u0639\u062f.',
      '\u0647\u0646\u0648\u0632 \u0686\u06a9\u06cc \u0628\u0627 \u0627\u06cc\u0646 \u0634\u062e\u0635 \u062b\u0628\u062a \u0646\u0634\u062f\u0647.':
        '\u0644\u0627 \u062a\u0648\u062c\u062f \u0634\u064a\u0643\u0627\u062a \u0645\u0639 \u0647\u0630\u0627 \u0627\u0644\u0634\u062e\u0635 \u0628\u0639\u062f.',
